  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "RISK-APPROPRIATE",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md classifies T-001–T-005 high for execution-evidence contracts, trust boundaries, model eligibility, protected launch integration and notification controls. T-006/T-007 are medium with explicit limits to verified adoption/activation metadata, evaluation and release delivery; capability and authorization algorithm changes remain excluded."
    },
    {
      "id": "HIGH-CRITICAL-EVIDENCE",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Each high-risk task T-001–T-005 explicitly requires committed failing tests before implementation, captured Red→Green evidence and a named independent reviewer verdict in Done When. No critical task is declared."
    },
    {
      "id": "TASK-SIZE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "tasks.md T-004 Planned Files and Done When combine renderer/installer migration, protected review launcher/validator migration, run-record and GPT/Gemini transport integration, and role/skill/scheduled-automation migration. They additionally require Bash/PowerShell regressions, a complete maintained-caller sweep and actual installed-host validation. This exceeds a focused-session implementation unit; the six bullets conceal multiple independently verifiable integration areas."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "acceptance-tests.md covers T-003 configuration/discovery/identity failures through AC-012/014/016, T-004 consent and native-precedence failures through AC-011/014/018, and T-005 failed fetches/untrusted text through AC-017. T-006 Done When explicitly retains failed candidates and unavailable-provider limitations. CI tasks also have extensive conservative-fallback and missing-evidence cases."
    },
    {
      "id": "TEST-TYPE-MATCH",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001 separates deterministic unit/integration fixtures; T-002/T-004 name workflow and launcher integration across components. T-006 acceptance evaluation explicitly references AC-013/AC-019 and TEST-127, fixed comparisons and actual artifacts. T-007 distinguishes hosted acceptance from local fixtures. No unit-only claim is used for cross-component or hosted validation."
    },
    {
      "id": "ROLLBACK-PLAN",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001–T-005 each require documented and tested rollback in a disposable checkout with hashes and baseline results. Shared file ordering and rollback specifies force-full CI recovery and validated model pin/prior-release recovery without weakening identity, access or consent checks."
    },
    {
      "id": "SCOPE-DISJOINT",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md assigns bounded ownership for shared catalog, interpreter, policy and test files. Its T-001→T-007 blocker chain prevents simultaneous edits, while T-006/T-007 explicitly exclude algorithm repairs from adoption/activation metadata scope."
    },
    {
      "id": "DEPENDENCY-OVERLAP",
      "result": "FAIL",
      "severity": "Major",
      "finding": "tasks.md T-006 declares T-005 as its blocker, but T-005 only updates freshness reporting and explicitly never rewrites registry files. T-006 consumes the T-003 selector/policy and T-004 installed launch path, independently rediscovers availability and uses a pre-existing rubric; it names no T-005-produced input and shares no planned implementation file with T-005. This creates an unnecessary critical-path dependency."
    },
    {
      "id": "BUGFIX-DIAGNOSTIC-PATH",
      "result": "SKIP",
      "severity": "Major",
      "finding": "SKIP: no bugfix or debugging task in scope."
    }
  ],
  "findings": [
    {
      "check_id": "TASK-SIZE",
      "severity": "Major",
      "task_id": "T-004",
      "finding": "specs/ci-model-modernization/tasks.md T-004 Planned Files and Done When bundle at least four integration areas: renderer/installers, protected review launch/validation, run-record/panelist transports, and role/skill/self-improvement entry points. Cross-shell regressions, all-caller migration and actual installed-host validation further exceed a single focused session, risking incomplete consumer migration before independent verification. Split into ordered session-sized integration tasks while keeping each protected launcher and its validator together."
    },
    {
      "check_id": "DEPENDENCY-OVERLAP",
      "severity": "Major",
      "task_id": "T-006",
      "finding": "specs/ci-model-modernization/tasks.md T-006 Blockers names T-005 although its Scope and Done When consume T-003 policy/selector and T-004 launch integration, not freshness-maintenance output. T-005 explicitly cannot rewrite registry files, and the two tasks share no planned implementation file. This spurious blocker unnecessarily delays adoption evaluation; depend on the actual producing tasks or identify a concrete required T-005 artifact."
    }
  ]
